def what(happens, mins, look):
    return '<div class="what"><p><b>붙여 넣으면</b> %s</p><p><b>걸리는 시간</b> %s</p><p><b>끝나면 볼 것</b> %s</p></div>'%(happens,mins,look)

def shot23(name, alt, caption):
    # 예시 그림이 아직 없으면(빌더를 처음 돌릴 때) 자리 글만 둔다
    if not os.path.exists(os.path.join(GAL, name)):
        return '<p class="sub">[예시 그림 자리: %s]</p>' % name
    return shot(name, alt, caption)

def video23(name, poster, caption):
    # 예시 영상(작은 mp4)을 페이지 안에 넣는다. 없으면 자리 글만
    import base64
    p = os.path.join(GAL, name)
    if not os.path.exists(p):
        return '<p class="sub">[예시 영상 자리: %s]</p>' % name
    src = 'data:video/mp4;base64,' + base64.b64encode(open(p, 'rb').read()).decode()
    pst = os.path.join(GAL, poster)
    pattr = (' poster="data:image/jpeg;base64,%s"' % base64.b64encode(open(pst, 'rb').read()).decode()) if os.path.exists(pst) else ''
    return '<figure class="shot vid"><video controls muted playsinline preload="metadata"%s src="%s"></video><figcaption>%s</figcaption></figure>' % (pattr, src, caption)


